"""Plantilla editable 'Cambio de Fase de Nuevos Productos' (se crea solo si no existe)."""
from datetime import datetime, timezone
from config import db

TEMPLATE = {'template_id': 'new_product_phase_change', 'body_html': '<div style="font-family:Arial,sans-serif;max-width:650px;margin:0 auto;padding:20px;">\n  <div style="background:#003366;padding:20px;text-align:center;border-radius:8px 8px 0 0;">\n    <h1 style="color:white;margin:0;font-size:20px;">Actualización de Nuevos Proyectos</h1>\n    <p style="color:#93c5fd;margin:4px 0 0;font-size:14px;">Producto: {nombre_producto} — Banco: {nombre_banco}</p>\n  </div>\n  <div style="background:#f8fafc;padding:25px;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 8px 8px;">\n    <p style="color:#334155;font-size:14px;">Reciban un cordial saludo.</p>\n    <p style="color:#475569;font-size:14px;">\n      El día de hoy ({fecha_sistema}), el proyecto de Integración del Medio de Pago <strong>{nombre_producto}</strong> ({componente}),\n      para el Banco/Entidad: <strong>{nombre_banco}</strong>, ha pasado del estatus <strong>{estatus_anterior}</strong> al Estatus:\n      <span style="color:#003366;font-weight:bold;font-size:15px;">{nueva_fase}</span>.\n    </p>\n    <table style="font-size:13px;color:#475569;margin:10px 0;border-collapse:collapse;">\n      <tr><td style="padding:3px 12px 3px 0;">Días en la fase anterior:</td><td><strong>{dias_fase_saliente}</strong></td></tr>\n      <tr><td style="padding:3px 12px 3px 0;">Días totales del proyecto:</td><td><strong>{dias_totales_proyecto}</strong></td></tr>\n    </table>\n    <p style="color:#475569;font-size:14px;">Será atendido por el siguiente equipo de trabajo:</p>\n    {equipo_trabajo}\n    <hr style="border:none;border-top:1px solid #e2e8f0;margin:20px 0;">\n    {Firma_Notificacion_Global}\n    <p style="color:#94a3b8;font-size:12px;text-align:center;">Sistema de Gestión de Proyectos — Mega Soft</p>\n  </div>\n</div>', 'description': 'Notifica cada cambio de fase (Negociación → DESA → SQA → IMPLE → PreProd → Primer Prod → Masificación) con el equipo asignado', 'is_active': True, 'is_project_template': True, 'name': 'Cambio de Fase de Nuevos Productos', 'subject': 'Actualización de Nuevos Proyectos - Producto: {nombre_producto} - Banco: {nombre_banco} → {nueva_fase}'}


async def ensure_np_phase_template():
    now = datetime.now(timezone.utc).isoformat()
    await db.email_templates.update_one({"template_id": TEMPLATE["template_id"]},
                                        {"$setOnInsert": {**TEMPLATE, "created_at": now, "updated_at": now}}, upsert=True)
